8	const readAll = async (stream: NodeJS.ReadableStream): Promise<string> => {
9	  const chunks: string[] = [];
10	  stream.setEncoding("utf8");
11	  for await (const chunk of stream) chunks.push(chunk as string);
12	  return chunks.join("");
13	};
