1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const FREE_TYPES = 3;
8	
9	// Opaque identity key: two cards are the same monster type when their keys
10	// match. Rank is part of the identity, so ranked variants count separately.
11	const monsterTypeKey = (card: Card): string => `${card.monster}-${card.rank}`;
12	
13	export const scoreArmy = (army: Card[]): number => {
14	  const distinctTypeCount = new Set(army.map(monsterTypeKey)).size;
15	  const typesBeyondFree = distinctTypeCount - FREE_TYPES;
16	  const pointsPerSphinx = typesBeyondFree > 0 ? 2 * typesBeyondFree : 1;
17	  const sphinxCount = army.filter((card) => card.monster === SPHINX).length;
18	  return sphinxCount * pointsPerSphinx;
19	};
20

1	import { describe, it, expect } from "vitest";
