7	  it("scores an empty army as 0", () => {
8	    expect(scoreArmy([])).toBe(0);
9	  });
10	  it("scores an army of non-sphinx monsters as 0 — [hydra, zombie] is 0", () => {
11	    expect(scoreArmy([{ monster: "hydra" }, { monster: "zombie" }])).toBe(0);
12	  });
13	
14	  // A single Sphinx, few types: the "else 1" branch
