16	    expect(scoreArmy([{ monster: "sphinx" }])).toBe(1);
17	  });
18	  it("scores a sphinx with two types as 1 — [sphinx, hydra] is 1", () => {
19	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }])).toBe(1);
20	  });
21	  it("scores a sphinx with exactly three types as 1 — [sphinx, hydra, zombie] is 1", () => {
22	    expect(
23	      scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }, { monster: "zombie" }]),
24	    ).toBe(1);
25	  });
